// Извлекаем данные из предыдущих узлов.
// Обратите внимание, что 'Date & Time' возвращает объект,
// и мы можем получить отформатированную строку из него.
const userQuestion = $('Extract Text').item.json.text;
const searchResults = $('HTTP Request').item.json;

// Получаем отформатированную дату из узла Date & Time
// Здесь мы используем tomorrowDate, так как вы спрашивали про "завтрашнюю" дату
const tomorrowDate = $('Date & Time').item.json.tomorrowDate;

let formattedSearchResults = "";

// Проверяем, есть ли результаты поиска
if (searchResults && searchResults.items && searchResults.items.length > 0) {
  formattedSearchResults = "Вот результаты поиска в интернете:\n\n";
  for (const item of searchResults.items) {
    // Извлекаем название и краткое описание (snippet)
    const title = item.title;
    const snippet = item.snippet;
    formattedSearchResults += `Название: ${title}\nФрагмент: ${snippet}\n\n`;
  }
} else {
  formattedSearchResults = "В интернете не найдено релевантной информации.";
}

// Формируем итоговый промпт для AI-агента
const finalPrompt = `
Пользователь задал вопрос: "${userQuestion}"

Текущая дата: ${tomorrowDate}

Результаты поиска в интернете:
${formattedSearchResults}

На основе этой информации и твоей внутренней базы знаний, ответь на вопрос.
`;

// Возвращаем готовую строку промпта в новом JSON-объекте
return [{
  json: {
    finalPrompt: finalPrompt 
  }
}];

